"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[332],{77064:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","label":"Getting started","href":"/infinite-ocean/docs/intro","docId":"intro","unlisted":false},{"type":"link","label":"No Scripting Guide","href":"/infinite-ocean/docs/no-scripting","docId":"no-scripting","unlisted":false},{"type":"link","label":"Advanced Guide","href":"/infinite-ocean/docs/advanced","docId":"advanced","unlisted":false},{"type":"link","label":"Tutorial","href":"/infinite-ocean/docs/tutorial","docId":"tutorial","unlisted":false},{"type":"link","label":"Plugin guide","href":"/infinite-ocean/docs/plugin","docId":"plugin","unlisted":false},{"type":"link","label":"Scripting","href":"/infinite-ocean/docs/scripting","docId":"scripting","unlisted":false},{"type":"link","label":"Addons","href":"/infinite-ocean/docs/addons","docId":"addons","unlisted":false},{"type":"link","label":"Settings reference","href":"/infinite-ocean/docs/settings","docId":"settings","unlisted":false},{"type":"link","label":"Tags","href":"/infinite-ocean/docs/tags","docId":"tags","unlisted":false},{"type":"link","label":"Presets","href":"/infinite-ocean/docs/presets","docId":"presets","unlisted":false},{"type":"link","label":"Performance","href":"/infinite-ocean/docs/performance","docId":"performance","unlisted":false},{"type":"link","label":"Licence and support","href":"/infinite-ocean/docs/licensing","docId":"licensing","unlisted":false}]},"docs":{"addons":{"id":"addons","title":"Addons","description":"Addons are optional scripts the plugin installs next to the module in ReplicatedStorage (OceanBuoyancy, OceanSwimming and so on). Each is independent: the module works without any of them, and you can add or remove one at any time from More > Addons or during Quick Start. An installed addon gets its own dropdown at the top of the panel with its settings; those settings are attributes on the addon script, so scripts can change them too.","sidebar":"defaultSidebar"},"advanced":{"id":"advanced","title":"Advanced Guide","description":"For developers who script. Install the plugin, install the module, then drive the sea from code: this page walks through each core feature of the API.","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"Getting started","description":"Infinite Ocean is an infinite, animated sea for Roblox. Pick the guide that fits you and it walks you through the rest.","sidebar":"defaultSidebar"},"licensing":{"id":"licensing","title":"Licence and support","description":"Infinite Ocean is the work of KashTheKing.","sidebar":"defaultSidebar"},"no-scripting":{"id":"no-scripting","title":"No Scripting Guide","description":"Two things: install the plugin, then let the Quick Start build your sea. Nothing is typed, and the whole thing takes about two minutes.","sidebar":"defaultSidebar"},"performance":{"id":"performance","title":"Performance","description":"The sea is built to hold a high frame rate on ordinary clients. This page explains what costs what, so you can spend where it shows.","sidebar":"defaultSidebar"},"plugin":{"id":"plugin","title":"Plugin guide","description":"The panel is one dock widget. Every control has a hover tooltip, and every setting has a one-line hint under it. Type in the Search box to filter every section down to matching settings.","sidebar":"defaultSidebar"},"presets":{"id":"presets","title":"Presets","description":"A preset is a plain table of settings that applies on top of whatever is set. Three kinds, all in Ocean.Presets and in the panel\'s Presets heading. Presets are starting points, not the limit: every value they set is a slider in the panel, so start from the closest one and make the sea your own. Save the result with Save current and it becomes a preset too.","sidebar":"defaultSidebar"},"scripting":{"id":"scripting","title":"Scripting","description":"The module is one ModuleScript, ReplicatedStorage.Ocean, that works on the server and on every client. Its two child scripts start it; you only require it.","sidebar":"defaultSidebar"},"settings":{"id":"settings","title":"Settings reference","description":"Every setting is an attribute on ReplicatedStorage.Ocean. The plugin panel edits them; scripts can too (server side)SetAttribute(\\"WaveHeight\\", 1.5) or, with validation and clamping, Settings.Set. Settings marked weather can be overridden per weather (see Scripting); settings marked rebuilds mesh rebuild the surface when changed.","sidebar":"defaultSidebar"},"tags":{"id":"tags","title":"Tags","description":"Everything hooks into the sea through CollectionService tags. Add them from the panel\'s Tags section (select something, press Tag selection), from the Tag Editor, or from a script. Attributes on the tagged instance tune each one. The tag names can be renamed under Tags in the settings, or by double-clicking a tag\'s title in the panel.","sidebar":"defaultSidebar"},"tutorial":{"id":"tutorial","title":"Tutorial","description":"Fifteen minutes from an empty baseplate to a sea with a calm bay, a boat you can steer, players who swim, and a storm your server can call in. No code until the last step.","sidebar":"defaultSidebar"}}}}')}}]);